type EventSeed = {
  id: string; name: string; years: [number, number]; type: WarEvent['type']; kind: WarEvent['kind']; scale: WarEvent['scale']; confidence: WarEvent['confidence'];
  summary: string; background: string; result: string; impact: string; participants: Array<[string, string?]>; place: [string, string, number, number, WarEvent['locations'][number]['role']]; source: Source; tags: string[]; route?: Array<[string, number, number]>;
};

function event(seed: EventSeed): WarEvent {
  const [name, modernName, latitude, longitude, role] = seed.place;
  return {
    id: seed.id, scenarioId: HAN_THREE_KINGDOMS_SCENARIO_ID, name: seed.name, startYear: seed.years[0], endYear: seed.years[1], type: seed.type, kind: seed.kind, scale: seed.scale, confidence: seed.confidence,
    summary: seed.summary, background: seed.background, result: seed.result, impact: seed.impact,
    participants: seed.participants.map(([participantName, polityId], index) => ({ id: `${seed.id}-${index}`, name: participantName, polityId })),
    locations: [{ id: `${seed.id}-location`, name, modernName, latitude, longitude, role }],
    routes: seed.route ? [{ actorId: seed.participants[0][1] ?? seed.id, description: `${seed.participants[0][0]}的主要进军方向，按史料叙事作概括表达。`, points: seed.route.map(([pointName, pointLatitude, pointLongitude]) => ({ name: pointName, latitude: pointLatitude, longitude: pointLongitude })) }] : undefined,
    sources: [seed.source, atlas], tags: seed.tags,
  };
}

