const clockwise = (coordinates: number[][]) => [...coordinates].reverse();
const polygon = (coordinates: number[][]): TerritorySnapshot['geometry'] => ({ type: 'Polygon', coordinates: [clockwise(coordinates)] });
const territory = (id: string, polityId: string, startYear: number, endYear: number, coordinates: number[][], description: string, control: TerritorySnapshot['control'], confidence: TerritorySnapshot['confidence'] = 'low', labelPosition?: [number, number]): TerritorySnapshot => ({ id, scenarioId: HAN_THREE_KINGDOMS_SCENARIO_ID, polityId, startYear, endYear, geometry: polygon(coordinates), labelPosition, description, control, confidence, sources: [atlas, study] });

